/* dbo.agents + sp_agents / _all / _one — generated by posgmo-factory (PRD tests/prd_agent.json, 2026-11-18), reviewed by hand.
   Run on DEV first, then QA, then PROD. Then 2026-11-18_agents_seed.sql. */
IF OBJECT_ID('dbo.agents','U') IS NULL
BEGIN
CREATE TABLE [dbo].[agents] (
    agentId         INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_agents PRIMARY KEY CLUSTERED,
    agentKey        NVARCHAR(80) NOT NULL UNIQUE,
    name            NVARCHAR(120) NOT NULL,
    description     NVARCHAR(500) NULL,
    area            NVARCHAR(20) NOT NULL CHECK (area IN ('whatsapp','pos_support','loans','extraction','other')),
    endpoint        NVARCHAR(120) NOT NULL CHECK (endpoint LIKE '/%'),
    model           NVARCHAR(60) NULL,
    customerFacing  BIT NOT NULL DEFAULT 0,
    status          NVARCHAR(20) NOT NULL DEFAULT 'activo' CHECK (status IN ('activo','retirado')),
    created_At      DATETIME NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at      DATETIME NULL
);
END
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_agents_area') CREATE NONCLUSTERED INDEX IX_agents_area ON dbo.agents (area);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_agents_status') CREATE NONCLUSTERED INDEX IX_agents_status ON dbo.agents (status);

GO
CREATE OR ALTER PROCEDURE [dbo].[sp_agents]
    @pjsonfile VARCHAR(MAX)
AS
SET NOCOUNT ON;

DECLARE @Outputmessage NVARCHAR(MAX) = '{
  "result": [
    { "value": "", "msg": "", "error": "" }
  ]
}';

BEGIN TRY
    DECLARE @action INT;
    SET @action = (
        SELECT TOP 1 TRY_CONVERT(INT, JSON_VALUE(value, '$.action'))
        FROM OPENJSON(@pjsonfile, '$.agents')
    );

    DECLARE @payload TABLE (
        agentId         INT NULL,
        agentKey        NVARCHAR(80) NULL,
        name            NVARCHAR(120) NULL,
        description     NVARCHAR(500) NULL,
        area            NVARCHAR(20) NULL,
        endpoint        NVARCHAR(120) NULL,
        model           NVARCHAR(60) NULL,
        customerFacing  BIT NULL,
        status          NVARCHAR(20) NULL
    );

    INSERT INTO @payload (agentId, agentKey, name, description, area, endpoint, model, customerFacing, status)
    SELECT
        TRY_CONVERT(INT, JSON_VALUE(value, '$.agentId')),
        JSON_VALUE(value, '$.agentKey'),
        JSON_VALUE(value, '$.name'),
        JSON_VALUE(value, '$.description'),
        JSON_VALUE(value, '$.area'),
        JSON_VALUE(value, '$.endpoint'),
        JSON_VALUE(value, '$.model'),
        TRY_CONVERT(BIT, JSON_VALUE(value, '$.customerFacing')),
        JSON_VALUE(value, '$.status')
    FROM OPENJSON(@pjsonfile, '$.agents');

    BEGIN TRANSACTION;

    IF @action = 1 -- INSERT
    BEGIN
        -- Validate for duplicate agentKey within the payload
        IF EXISTS (SELECT 1 FROM @payload GROUP BY agentKey HAVING COUNT(*) > 1)
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Duplicate agentKey found in payload.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END;

        -- Validate for duplicate agentKey against existing records
        IF EXISTS (SELECT 1 FROM @payload p JOIN dbo.agents a ON p.agentKey = a.agentKey WHERE p.agentKey IS NOT NULL)
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Agent with this agentKey already exists.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END;

        INSERT INTO dbo.agents (agentKey, name, description, area, endpoint, model, customerFacing, status, created_At)
        SELECT
            p.agentKey,
            p.name,
            p.description,
            p.area,
            p.endpoint,
            p.model,
            ISNULL(p.customerFacing, 0), -- Default for customerFacing
            ISNULL(p.status, 'activo'), -- Default for status
            SYSUTCDATETIME()
        FROM @payload p;

        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Inserted Successfully');
    END
    ELSE IF @action = 2 -- UPDATE
    BEGIN
        -- Validate for duplicate agentKey against existing records, excluding the current record being updated
        IF EXISTS (SELECT 1 FROM @payload p JOIN dbo.agents a ON p.agentKey = a.agentKey WHERE p.agentKey IS NOT NULL AND a.agentId <> p.agentId)
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Another agent with this agentKey already exists.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END;

        UPDATE a
        SET
            name = ISNULL(p.name, a.name),
            description = ISNULL(p.description, a.description),
            area = ISNULL(p.area, a.area),
            endpoint = ISNULL(p.endpoint, a.endpoint),
            model = ISNULL(p.model, a.model),
            customerFacing = ISNULL(p.customerFacing, a.customerFacing),
            status = ISNULL(p.status, a.status),
            updated_at = SYSUTCDATETIME()
        FROM dbo.agents a
        INNER JOIN @payload p ON a.agentId = p.agentId;

        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Updated Successfully');
    END
    ELSE IF @action = 3 -- RETIRE (soft delete)
    BEGIN
        UPDATE a
        SET
            status = 'retirado',
            updated_at = SYSUTCDATETIME()
        FROM dbo.agents a
        INNER JOIN @payload p ON a.agentId = p.agentId;

        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Retired Successfully');
    END

    COMMIT TRANSACTION;

Finish:
    SELECT
        JSON_VALUE(value,'$.value') AS value,
        JSON_VALUE(value,'$.msg')   AS msg,
        JSON_VALUE(value,'$.error') AS error
    FROM OPENJSON(@Outputmessage,'$.result');

END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
    SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', ERROR_MESSAGE());

    SELECT
        JSON_VALUE(value,'$.value') AS value,
        JSON_VALUE(value,'$.msg')   AS msg,
        JSON_VALUE(value,'$.error') AS error
    FROM OPENJSON(@Outputmessage,'$.result');
END CATCH;

GO
CREATE OR ALTER PROCEDURE [dbo].[sp_agents_all]
    @pjsonfile VARCHAR(MAX)
AS
SET NOCOUNT ON;
BEGIN
    DECLARE @filterArea NVARCHAR(20) = (
        SELECT TOP 1 JSON_VALUE(value, '$.area')
        FROM OPENJSON(@pjsonfile, '$.agents')
    );
    DECLARE @filterStatus NVARCHAR(20) = (
        SELECT TOP 1 JSON_VALUE(value, '$.status')
        FROM OPENJSON(@pjsonfile, '$.agents')
    );
    DECLARE @searchQuery NVARCHAR(255) = (
        SELECT TOP 1 JSON_VALUE(value, '$.search')
        FROM OPENJSON(@pjsonfile, '$.agents')
    );

    SELECT
        [agentId],
        ISNULL([agentKey], '') AS agentKey,
        ISNULL([name], '') AS name,
        ISNULL([description], '') AS description,
        ISNULL([area], '') AS area,
        ISNULL([endpoint], '') AS endpoint,
        ISNULL([model], '') AS model,
        ISNULL(CAST([customerFacing] AS INT), 0) AS customerFacing,
        ISNULL([status], '') AS status,
        [created_At],
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM dbo.agents
    WHERE
        (@filterArea IS NULL OR area = @filterArea)
        AND (@filterStatus IS NULL OR status = @filterStatus)
        AND (@searchQuery IS NULL OR name LIKE '%' + @searchQuery + '%' OR description LIKE '%' + @searchQuery + '%' OR agentKey LIKE '%' + @searchQuery + '%')
    ORDER BY
        area, name
    FOR JSON AUTO, ROOT('agents');
END;

GO
CREATE OR ALTER PROCEDURE [dbo].[sp_agents_one]
    @pjsonfile VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @agentId INT;
    DECLARE @agentKey NVARCHAR(80);

    SELECT TOP 1
        @agentId = TRY_CONVERT(INT, JSON_VALUE(value, '$.agentId')),
        @agentKey = JSON_VALUE(value, '$.agentKey')
    FROM OPENJSON(@pjsonfile, '$.agents');

    SELECT
        agentId,
        ISNULL(agentKey, '') AS agentKey,
        ISNULL(name, '') AS name,
        ISNULL(description, '') AS description,
        ISNULL(area, '') AS area,
        ISNULL(endpoint, '') AS endpoint,
        ISNULL(model, '') AS model,
        ISNULL(CAST(customerFacing AS INT), 0) AS customerFacing,
        ISNULL(status, '') AS status,
        created_At,
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM dbo.agents
    WHERE
        (agentId = @agentId AND @agentId IS NOT NULL)
        OR (agentKey = @agentKey AND @agentKey IS NOT NULL)
    FOR JSON AUTO, ROOT('agents');
END;

